const retentionLock = `-- name: RetentionLock :one
SELECT pg_try_advisory_xact_lock(1702170217)
`

// One retention run at a time across every API instance.
func (q *Queries) RetentionLock(ctx context.Context) (bool, error) {
	row := q.db.QueryRow(ctx, retentionLock)
	var pg_try_advisory_xact_lock bool
	err := row.Scan(&pg_try_advisory_xact_lock)
	return pg_try_advisory_xact_lock, err
}
